import sys

input = sys.stdin.read
data = input().split()

n = int(data[0])
array = list(map(int, data[1:n+1]))
target = int(data[n+1])

def search_rotated_sorted_array(array, target):
    left, right = 0, len(array) - 1

    while left <= right:
        mid = (left + right) // 2

        if array[mid] == target:
            return mid
        elif array[left] <= array[mid]:
            if array[left] <= target < array[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if array[mid] < target <= array[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

result = search_rotated_sorted_array(array, target)
print(result)

